@startuml

class EBike {
  + modelName : string
  + weight : float
}

class Frame {
  + material : string
}

class DriveSystem {
  + maxTorque : float
}

class Motor {
  + powerOutput : float
}

class Controller {
  + currentState : ControllerState
  + updateState() : void
}

class BasicController {}

class AdvancedController {
  + nextInspectionDate : date
  + estimateMaintenance() : date
}

class Battery {
  + storedEnergyWh : float
  + isRemovable : boolean
}

class Wheel {
  + diameter : float
}

enum ControllerState {
  On
  Off
  Charging
}

EBike "1" *-- "1" Frame
EBike "1" *-- "1" DriveSystem
EBike "1" *-- "1" Controller
EBike "1" *-- "0..1" Battery
Frame "1" *-- "2" Wheel
DriveSystem "1" *-- "1" Motor
BasicController --|> Controller
AdvancedController --|> Controller
Controller --> Battery : controls
Controller --> DriveSystem : commands

@enduml

